import heapq

def match(orders):
    buy_heap = []   # entries: (-price, time, id) for resting buy orders
    sell_heap = []  # entries: (price, time, id) for resting sell orders
    book = {}       # id -> order record dict
    trades = []
    time_counter = 0

    for order in orders:
        time_counter += 1
        typ = order[0]

        if typ == 'cancel':
            oid = order[1]
            if oid in book and book[oid]['status'] == 'active':
                book[oid]['status'] = 'cancelled'
            continue

        if typ == 'limit':
            _, oid, side, price, qty = order
        elif typ == 'ioc':
            _, oid, side, price, qty = order
        elif typ == 'market':
            _, oid, side, qty = order
            price = None
        else:
            # unknown order type, ignore
            continue

        rec = {
            'side': side,
            'price': price,
            'qty': qty,
            'time': time_counter,
            'status': 'active',
            'type': typ
        }
        book[oid] = rec

        if side == 'buy':
            opp_heap = sell_heap
        else:
            opp_heap = buy_heap

        while rec['qty'] > 0:
            # clean invalid entries from top of opposite heap
            while opp_heap:
                top = opp_heap[0]
                top_id = top[2]
                top_rec = book.get(top_id)
                if top_rec is None or top_rec['status'] != 'active' or top_rec['qty'] <= 0:
                    heapq.heappop(opp_heap)
                    continue
                break

            if not opp_heap:
                break

            top = opp_heap[0]
            top_id = top[2]
            top_rec = book[top_id]
            top_price = top_rec['price']

            # check price compatibility (None means market order, matches any price)
            if price is not None:
                if side == 'buy' and top_price > price:
                    break
                if side == 'sell' and top_price < price:
                    break

            trade_qty = min(rec['qty'], top_rec['qty'])
            trade_price = top_rec['price']

            if side == 'buy':
                trades.append([oid, top_id, trade_price, trade_qty])
            else:
                trades.append([top_id, oid, trade_price, trade_qty])

            rec['qty'] -= trade_qty
            top_rec['qty'] -= trade_qty

            if top_rec['qty'] == 0:
                top_rec['status'] = 'done'
                heapq.heappop(opp_heap)
            # else: partially filled resting order stays at front of queue

        if typ == 'limit':
            if rec['qty'] > 0 and rec['status'] == 'active':
                if side == 'buy':
                    heapq.heappush(buy_heap, (-rec['price'], rec['time'], oid))
                else:
                    heapq.heappush(sell_heap, (rec['price'], rec['time'], oid))
            else:
                rec['status'] = 'done'
        else:
            # ioc or market: remainder discarded, never rests
            rec['status'] = 'done'

    return trades

